<template><div class="wrap"><div class="page-head"><h1>Bet of the Day</h1><p class="muted">Two AI-assisted featured picks selected from upcoming matches.</p></div><div v-if="items.length" class="grid2"><article v-for="p in items" :key="p._id" class="card featured"><span class="tag">{{p.risk||'Low risk'}}</span><h2>{{matchName(p.matchId)}}</h2><div class="prediction">{{p.prediction}}</div><div class="kpis"><div class="stat"><span class="muted small">Confidence</span><b>{{p.confidence}}%</b></div><div class="stat"><span class="muted small">Model</span><b style="font-size:15px">{{p.model}}</b></div></div><p class="muted" style="line-height:1.7">{{p.analysis}}</p><button class="btn" @click="play">{{auth.isLoggedIn?'Add to My Picks':'Sign up to play'}}</button></article></div><div v-else class="card empty">No Bet of the Day has been published yet.</div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {api} from '../services/api';import {useAuth} from '../stores/auth';const items=ref<any[]>([]),auth=useAuth(),router=useRouter();const matchName=(m:any)=>m?.homeTeamId?.name&&m?.awayTeamId?.name?`${m.homeTeamId.name} vs ${m.awayTeamId.name}`:'Featured match';function play(){if(auth.isLoggedIn)router.push('/dashboard');else router.push('/login')}onMounted(async()=>{try{items.value=(await api.get('/bet-of-day')).data.filter((x:any)=>['published','won','lost','void'].includes(x.status))}catch{}})</script>
